using STOREEX.Models; using System.Linq; using System.Web.Mvc;
namespace STOREEX.Controllers { [Authorize] public class InventoryController:Controller { private readonly StoreexDb db=new StoreexDb(); private const int CompanyId=1; public ActionResult Index(int? warehouseId){ViewBag.Warehouses=db.Warehouses.Where(x=>x.CompanyId==CompanyId&&x.IsActive).ToList();var q=db.WarehouseStocks.Where(x=>x.Product.CompanyId==CompanyId);if(warehouseId.HasValue)q=q.Where(x=>x.WarehouseId==warehouseId.Value);return View(q.OrderBy(x=>x.Product.Name).ToList());} public JsonResult Search(string q,int? warehouseId){q=(q??"").Trim();var data=db.WarehouseStocks.Where(x=>x.Product.CompanyId==CompanyId&&x.Product.IsActive&&(x.Product.Name.Contains(q)||x.Product.SKU==q||x.Product.Barcode==q));if(warehouseId.HasValue)data=data.Where(x=>x.WarehouseId==warehouseId.Value);return Json(data.Select(x=>new{x.ProductId=x.ProductId,x.ProductName=x.Product.Name,x.SKU=x.Product.SKU,x.Barcode=x.Product.Barcode,x.WarehouseId=x.WarehouseId,x.Quantity=x.Quantity,x.Minimum=x.Product.MinimumStock}).Take(100),JsonRequestBehavior.AllowGet);} protected override void Dispose(bool d){if(d)db.Dispose();base.Dispose(d);}}}